import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"The Settlement Layer. Chain Routing","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/settlement-layer.md","filePath":"architecture/settlement-layer.md"}'),n={name:"architecture/settlement-layer.md"};function o(s,e,l,d,h,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-settlement-layer-chain-routing" tabindex="-1">The Settlement Layer. Chain Routing <a class="header-anchor" href="#the-settlement-layer-chain-routing" aria-label="Permalink to &quot;The Settlement Layer. Chain Routing&quot;">​</a></h1><h2 id="the-decision-function" tabindex="-1">The decision function <a class="header-anchor" href="#the-decision-function" aria-label="Permalink to &quot;The decision function&quot;">​</a></h2><p><code>chooseSettlementRail(partnerId, amountUsd)</code> in <code>corridorRouter.mjs</code> decides where a transfer settles, using three real inputs:</p><ol><li><strong>Which chains the destination partner supports</strong>, a maintained configuration (<code>PARTNER_CHAIN_SUPPORT</code>), not a live capability query. In real payment integrations, partner chain support is documented and changes on the order of weeks or months, not per-request, a config file kept in sync with partner documentation <em>is</em> the real-world integration process here.</li><li><strong>Which of those chains carry a MiCA-compliant, natively-issued stablecoin</strong> (<code>COMPLIANT_STABLECOIN_CHAINS</code>), as of mid-2026, USDC and EURC only. USDT is deliberately excluded: delisted from major EU venues, and Tether has stated no intention to pursue MiCA authorisation.</li><li><strong>Whether the amount stays within Hedera&#39;s real liquidity depth</strong> , a live check against DeFiLlama (<code>liquidity.mjs</code>), not an invented number, cached for 15 minutes since DEX depth doesn&#39;t move meaningfully minute to minute.</li></ol><p>Hedera is preferred whenever it&#39;s viable, one network for both trust and settlement is a simpler custody story. It falls back only when the partner requires a different chain, or the amount is large enough that the researched liquidity depth suggests visible slippage.</p><h2 id="what-s-genuinely-executed-vs-not-executed" tabindex="-1">What&#39;s genuinely executed vs. not executed <a class="header-anchor" href="#what-s-genuinely-executed-vs-not-executed" aria-label="Permalink to &quot;What&#39;s genuinely executed vs. not executed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chain</th><th>Execution</th></tr></thead><tbody><tr><td><strong>Hedera</strong></td><td>Fully real, a genuine HTS token transfer on testnet, a real transaction ID, verifiable on HashScan</td></tr><tr><td><strong>Ethereum / Solana / Base</strong></td><td>The <em>decision</em> is real and anchored; actual execution is a clearly labeled non-event, no funded testnet credentials exist for these chains in this project yet</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This project deliberately does not fabricate a transaction reference for a chain it cannot actually reach. See <a href="./../project/roadmap.html">Roadmap</a> for what full multi-chain execution would require.</p></div><h2 id="bridging-when-it-s-needed" tabindex="-1">Bridging, when it&#39;s needed <a class="header-anchor" href="#bridging-when-it-s-needed" aria-label="Permalink to &quot;Bridging, when it&#39;s needed&quot;">​</a></h2><p>As of mid-2026, Circle&#39;s Cross-Chain Transfer Protocol (CCTP) v1 is reported to already route Hedera; CCTP v2 (fast transfer) support is described elsewhere as still rolling out. Where CCTP isn&#39;t available, the design falls back to <strong>Circle Mint redeem-and-reissue</strong>, performed by the licensed partner, never by us, consistent with the non-custodial model throughout this project. This is a fast-moving detail; re-verify before relying on a specific bridge method.</p><h2 id="why-base-is-included-as-a-fallback" tabindex="-1">Why Base is included as a fallback <a class="header-anchor" href="#why-base-is-included-as-a-fallback" aria-label="Permalink to &quot;Why Base is included as a fallback&quot;">​</a></h2><p>Base carries native USDC with roughly <strong>$4.1–4.3B in supply</strong> (~5.8% of global USDC supply, mid-2026), smaller than Ethereum (~70%) or Solana (~10–20%+), but with very high transaction velocity. One caveat worth stating plainly: a large share of that volume is concentrated in a handful of DeFi pools (e.g. Aerodrome), not necessarily representative of liquidity available for payment settlement specifically. Base is ranked in <code>FALLBACK_CHAIN_PRIORITY</code> by its real, cited supply figure, not by headline transaction volume.</p><h2 id="the-four-non-hedera-fallback-chains-in-priority-order" tabindex="-1">The four non-Hedera fallback chains, in priority order <a class="header-anchor" href="#the-four-non-hedera-fallback-chains-in-priority-order" aria-label="Permalink to &quot;The four non-Hedera fallback chains, in priority order&quot;">​</a></h2><p>Hedera is preferred whenever it&#39;s viable (see above). When it isn&#39;t, the partner doesn&#39;t support it, or the amount exceeds Hedera&#39;s safe liquidity threshold, the router falls back to one of four chains, in this order:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Chain</th><th>USDC liquidity</th><th>Note</th></tr></thead><tbody><tr><td>1</td><td><strong>Ethereum</strong></td><td>~70% of global USDC supply</td><td>Deepest liquidity, highest gas cost</td></tr><tr><td>2</td><td><strong>Solana</strong></td><td>~$15-16B, fastest-growing</td><td>Leading stablecoin <em>payment volume</em> specifically</td></tr><tr><td>3</td><td><strong>Base</strong></td><td>~$4.1-4.3B (~5.8% of global USDC)</td><td>High transaction velocity, concentrated in a few DeFi pools</td></tr><tr><td>4</td><td><strong>BNB Chain</strong></td><td>~$14B total stablecoin supply, but only ~34-40% is USDC (rest is USDT, not MiCA-compliant)</td><td>The USDC-specific slice is roughly comparable to Base&#39;s total -- the headline $14B figure overstates what&#39;s usable for our EU leg</td></tr></tbody></table><p>All four are first-class CCTP (Cross-Chain Transfer Protocol) chains, meaning native burn-and-mint transfer without a third-party bridge&#39;s wrap risk. All four carry natively-issued USDC (Circle mints directly on each), which is why they&#39;re viable candidates at all -- a bridged/wrapped USDC would carry the bridge&#39;s own risk on top of everything else.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>BNB Chain&#39;s total stablecoin figure is dominated by USDT, which is excluded from this design (see <a href="./../legal/regulatory-landscape.html">Regulatory Landscape</a>). Citing the $14B headline number without this caveat would overstate the chain&#39;s relevant liquidity by roughly 2-3x.</p></div>',17)])])}const f=t(n,[["render",o]]);export{p as __pageData,f as default};
